      keyInfo = getRequiredKeyInfo(required_expressions[i]);
      key = keyInfo.keyName;
    } catch (e) {
      err = e;
      break;
    }

    if (keyInfo.pathKey)
      getFunc = getPath;
    else if (extraOption[key])
      getFunc = getExtra;
    else
      getFunc = getValue;

    val = getFunc(req, key);
    if (keyInfo.type === 'number') {
      if (isNaN(val)) {
        err = new Error('The parameter value is not a number : ' + key);
        err.code = 400;
        break;
      }
      options[key] = parseFloat(val);
    } else {
      options[key] = val;
    }

    if (!options[key]) {
      err = new Error('No Request Data For Required : ' + key);
      err.code = 400;
      break;
    }
  }

  return {
    err: err,
    params: options
  };
}

